const { ethers } = require('ethers');
const fs = require('fs');

// Contract source - simplified KeyringGateway
const contractSource = `
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract KeyringGateway {
    address public owner;
    bool public initialized;
    
    struct TallyVote {
        address governorAddress;
        uint256 proposalId;
        uint8 support;
        string reason;
    }
    
    event tallySignVote(address indexed sender, TallyVote vote);
    
    function initialize(address _owner) external {
        require(!initialized, "Already initialized");
        owner = _owner;
        initialized = true;
    }
    
    function signTallyVote(
        address governorAddress,
        uint256 proposalId,
        uint8 support,
        string calldata reason
    ) external {
        require(governorAddress != address(0), "Invalid governor address");
        require(support <= 2, "Invalid support value");
        
        TallyVote memory vote = TallyVote({
            governorAddress: governorAddress,
            proposalId: proposalId,
            support: support,
            reason: reason
        });
        
        emit tallySignVote(msg.sender, vote);
    }
}`;

// Compiled bytecode for the above contract
const bytecode = "";

async function deployKeyringGateway() {
    const provider = new ethers.providers.JsonRpcProvider('https://arb1.arbitrum.io/rpc');
    const wallet = new ethers.Wallet('0x73b248b923fd70a158cfe0aa73e348a38ec8cb73e39cb6f0cd3f573f8c095b41', provider);
    const owner = '0x8A9219e171Fa297840414df8689e4D7A0cE0d662';
    
    console.log('🚀 Deploying KeyringGateway to Arbitrum...');
    console.log('Deployer:', wallet.address);
    console.log('Owner:', owner);
    
    // ABI for the contract
    const abi = [
        "function initialize(address _owner) external",
        "function signTallyVote(address governorAddress, uint256 proposalId, uint8 support, string calldata reason) external",
        "event tallySignVote(address indexed sender, tuple(address governorAddress, uint256 proposalId, uint8 support, string reason) vote)"
    ];
    
    try {
        // Deploy contract
        const factory = new ethers.ContractFactory(abi, bytecode, wallet);
        const contract = await factory.deploy();
        await contract.deployed();
        
        console.log('✅ Contract deployed at:', contract.address);
        
        // Initialize the contract
        console.log('🔧 Initializing contract...');
        const initTx = await contract.initialize(owner);
        await initTx.wait();
        
        console.log('✅ Contract initialized!');
        console.log('');
        console.log('📝 UPDATE YOUR ENV FILES:');
        console.log(`VITE_KEYRING_GATEWAY_ARBITRUM=${contract.address}`);
        console.log('');
        console.log('🔗 Arbitrum Explorer:');
        console.log(`https://arbiscan.io/address/${contract.address}`);
        
        return contract.address;
    } catch (error) {
        console.error('❌ Deployment failed:', error.message);
        throw error;
    }
}

deployKeyringGateway().catch(console.error);